 func findCommandFlag(command, flag string) (flagDoc, bool) {
 	doc, ok := findCommandDoc(command)
 	if !ok {
 		return flagDoc{}, false
 	}
 	for _, candidate := range doc.flags {
 		if candidate.name == flag {
 			return candidate, true
 		}
 	}
 	return flagDoc{}, false
 }

